command:
psql --no-psqlrc -v ON_ERROR_STOP=1 -v db="$OPLIA_DATABASE" -v app_user="$APP_DB_USER" -v idle="$IDLE_SECONDS" <<'SQL'
SELECT count(pg_terminate_backend(pid)) AS terminated FROM pg_stat_activity WHERE datname = :'db' AND usename = :'app_user' AND state = 'idle' AND state_change < now() - make_interval(secs => :'idle'::int) AND pid <> pg_backend_pid();
SQL
